  this.kvCache = this.tvm.detachFromCurrentScope(
    createKVCache(
      this.tvm.makeShapeTuple([defaultMaxNumSequence]), // max_num_sequence
      this.tvm.makeShapeTuple([maxTotalSeqLen]), // max_total_sequence_length
